const form=document.querySelector('#quoteForm');
document.querySelector('#year').textContent=new Date().getFullYear();
form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const msg=`Hi, I need a quote from Yalla Move UAE.%0A%0AName: ${d.get('name')}%0AMobile: ${d.get('phone')}%0AFrom: ${d.get('from')}%0ATo: ${d.get('to')}%0AService: ${d.get('service')}%0ADetails: ${d.get('details')}`;window.open(`https://wa.me/?text=${encodeURIComponent(decodeURIComponent(msg))}`,'_blank');document.querySelector('.form-status').textContent='Your WhatsApp enquiry is ready to send.'});
